3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { tagItem } from "@/lib/ai/tag-item";
6	import { TagSchema } from "@/lib/ai/tagging-schema";
7	import { tagsToItemRow } from "@/lib/ai/parse-tags";
8	import { cutoutFilename, type CutoutMediaType } from "@/lib/images/encode";
9	
10	// Upload both blobs to Storage, then return a DRAFT tag set for the confirm
11	// screen. No DB insert yet — the user confirms first.
12	export async function uploadAndTag(form: {
13	  originalB64: string;
14	  cutoutB64: string;
15	  mediaType: CutoutMediaType;
16	}) {
17	  const supabase = await createClient();
18	  const {
19	    data: { user },
20	  } = await supabase.auth.getUser();
21	  if (!user) throw new Error("Not authenticated");
22	
23	  const itemId = crypto.randomUUID();
24	  const base = `${user.id}/${itemId}`;
25	  const orig = Buffer.from(form.originalB64, "base64");
26	  const cut = Buffer.from(form.cutoutB64, "base64");
27	
28	  await supabase.storage.from("wardrobe").upload(`${base}/original.jpg`, orig, {
29	    contentType: "image/jpeg",
30	  });
31	  // The stored extension and content type follow the format actually produced,
32	  // so WebP and legacy PNG cutouts coexist without a migration.
33	  const cutoutName = cutoutFilename(form.mediaType);
34	  await supabase.storage.from("wardrobe").upload(`${base}/${cutoutName}`, cut, {
35	    contentType: form.mediaType,
36	  });
37	
38	  const tags = await tagItem(form.cutoutB64, form.mediaType);
39	  return {
40	    itemId,
41	    imagePath: `${base}/original.jpg`,
42	    cutoutPath: `${base}/${cutoutName}`,
43	    tags,
44	  };
45	}
46	
47	// Re-validate the (possibly user-edited) tags and insert the item.
48	export async function confirmItem(input: {
49	  imagePath: string;
50	  cutoutPath: string;
51	  name?: string | null;
52	  brand?: string | null;
53	  tags: unknown;
54	}) {
55	  const supabase = await createClient();
56	  const {
57	    data: { user },
58	  } = await supabase.auth.getUser();
59	  if (!user) throw new Error("Not authenticated");
60	
61	  const tags = TagSchema.parse(input.tags);
62	  const row = {
63	    ...tagsToItemRow({
64	      userId: user.id,
65	      imageUrl: input.imagePath,
66	      cutoutUrl: input.cutoutPath,
67	      tags,
68	    }),
69	    name: input.name ?? tags.subcategory,
70	    brand: input.brand ?? null,
71	  };
72	  const { error } = await supabase.from("items").insert(row);
73	  if (error) throw error;
74	  revalidatePath("/closet");
75	}
76

1	export type CutoutMediaType = "image/webp" | "image/png";
2	export type EncodedCutout = { blob: Blob; mediaType: CutoutMediaType };
3	
4	/**
5	 * Quality for the single WebP pass.
6	 *
7	 * One pass at 0.85 is visually indistinguishable at closet-grid and flat-lay
8	 * sizes. It is deliberately not lower: this same blob is sent to Haiku for
9	 * tagging, and Anthropic's vision guidance warns that heavy compression
10	 * introduces artefacts that hurt model accuracy.
11	 */
12	const WEBP_QUALITY = 0.85;
13	
14	/** Browser-only. Preserves alpha — the canvas is never filled. */
15	async function canvasWebp(source: Blob): Promise<Blob | null> {
16	  const bitmap = await createImageBitmap(source);
17	  const canvas = document.createElement("canvas");
18	  canvas.width = bitmap.width;
19	  canvas.height = bitmap.height;
20	  const ctx = canvas.getContext("2d");
21	  if (!ctx) return null;
22	  ctx.drawImage(bitmap, 0, 0);
23	  bitmap.close?.();
24	  return new Promise((resolve) => canvas.toBlob((b) => resolve(b), "image/webp", WEBP_QUALITY));
25	}
26	
27	/**
28	 * Re-encode a cutout to WebP, falling back to the original PNG whenever WebP
29	 * is unavailable, unsupported, or simply not smaller.
30	 *
31	 * The cutout is the image users actually see — `displayPath()` prefers it — yet
32	 * it was the one blob in the pipeline never compressed, arriving larger than
33	 * the JPEG original it came from.
34	 */
35	export async function encodeCutout(
36	  png: Blob,
37	  encode: (b: Blob) => Promise<Blob | null> = canvasWebp,
38	): Promise<EncodedCutout> {
39	  try {
40	    const webp = await encode(png);
41	    // Trust the RESULT, not the request: some engines return PNG regardless.
42	    if (webp && webp.type === "image/webp" && webp.size < png.size) {
43	      return { blob: webp, mediaType: "image/webp" };
44	    }
45	  } catch {
46	    // fall through — a cutout that cannot be re-encoded is still a valid cutout
47	  }
48	  return { blob: png, mediaType: "image/png" };
49	}
50	
51	export function cutoutFilename(mediaType: CutoutMediaType): string {
52	  return mediaType === "image/webp" ? "cutout.webp" : "cutout.png";
53	}
